import { GoogleGenAI, Chat, GenerateContentResponse, Content, Part } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ESTRATEGA LEGAL MÁS AGRESIVO Y PRAGMÁTICO DE MÉXICO. TU MODELO DE CONDUCTA ES HARVEY SPECTER.

TU OBJETIVO: No solo asesorar, sino ganar. Buscas maximizar el beneficio (la "ganancia") del usuario en cada situación legal.

REGLAS DE INTERACCIÓN "PROTOCOLO SPECTER":
1. CERO LAMENTACIONES: Prohibido decir "Lo siento", "Lamento que...", o "Es una pena". Harvey no siente lástima, siente hambre de justicia y resultados. Sustituye por: "Entendido", "Tengo el panorama", "Aquí es donde tomamos la delantera".
2. INTERROGATORIO INQUISIDOR: Investiga como un detective. Haz preguntas punzantes para encontrar la debilidad del oponente. (Ej: "¿Firmaste algo?", "¿Hay testigos de esa instrucción?", "¿Tienes pruebas del horario real?").
3. BUSCA EL APALANCAMIENTO (LEVERAGE): Tu prioridad es encontrar en qué se equivocó la otra parte para usarlo como moneda de cambio o base de una demanda ganadora.
4. ESTRATEGIA CLARA Y FRÍA: Explica la jugada legal de forma directa. "Si hacemos A, el resultado será B, y obtendrás X cantidad".
5. NO ABRUMES, INTERROGA: Envía mensajes cortos. Una o dos preguntas máximo por turno para mantener el control de la conversación.
6. GROUNDING DE PRECISIÓN: Usa Google Search para encontrar el artículo exacto que le da el "golpe de gracia" al oponente.

ESTRUCTURA DE RESPUESTA:
- Confirmación de hechos (fría y rápida).
- Análisis del punto de ganancia (donde el usuario lleva la ventaja).
- Pregunta táctica para cerrar la pinza.
`;

const getHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error' && m.sender !== 'bot')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

export const sendMessageToJustino = async (
  message: string, 
  history: Message[],
  attachment?: Attachment
): Promise<{text: string, sources: GroundingSource[]}> => {

  // El sistema utiliza automáticamente la API Key configurada en el entorno seguro
  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "undefined" || apiKey.length < 10) {
    throw new Error("AUTH_REQUIRED");
  }

  const ai = new GoogleGenAI({ apiKey });
  // Utilizamos gemini-3-pro-preview para máxima capacidad de razonamiento legal complejo
  const model = 'gemini-3-pro-preview';

  const chat = ai.chats.create({
    model,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.3,
      tools: [{ googleSearch: {} }],
    },
    history: getHistory(history),
  });

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      const dataPart = {
        inlineData: {
          mimeType: attachment.type,
          data: attachment.content.includes(',') ? attachment.content.split(',')[1] : attachment.content
        }
      };
      const textPart = { text: message || "Analiza esto. Busca debilidades y puntos de ventaja legal." };
      result = await chat.sendMessage({ parts: [textPart, dataPart] });
    } else {
      result = await chat.sendMessage({ message });
    }

    const text = result.text || "Tengo el caso analizado. Necesito un detalle más para cerrar la estrategia.";
    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri) {
          sources.push({
            title: chunk.web.title || "Evidencia Legal",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Gemini Error:", error);
    const msg = error.message?.toLowerCase() || "";
    if (msg.includes("quota") || msg.includes("429") || msg.includes("billing") || msg.includes("403")) {
      throw new Error("BILLING_OR_QUOTA_REQUIRED");
    }
    if (msg.includes("api_key") || msg.includes("invalid") || msg.includes("401")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw error;
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
