import React, { useState, useEffect } from 'react';
import { LandingPage } from './components/LandingPage';
import { OnboardingModal } from './components/OnboardingModal';
import { Dashboard } from './components/Dashboard';
import { LoginModal } from './components/LoginModal';
import { AdminLogin } from './components/AdminLogin';
import { AdminDashboard } from './components/AdminDashboard';
import { User, AppView, Message, VaultFile } from './types';
import { supabase } from './services/supabaseClient';

interface CustomWindow extends Window {
  aistudio: any;
}
declare const window: CustomWindow;

function App() {
  const [view, setView] = useState<AppView>('landing');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(1);
  const [isKeyConnected, setIsKeyConnected] = useState(true);

  const [user, setUser] = useState<User | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [vaultFiles, setVaultFiles] = useState<VaultFile[]>([]);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setIsKeyConnected(hasKey);
      }
    };
    checkKey();

    const urlParams = new URLSearchParams(window.location.search);
    const success = urlParams.get('success');

    if (success === 'true') {
        setView('onboarding');
        setOnboardingStep(3);
        window.history.replaceState({}, document.title, window.location.pathname);
    } else {
        const isSessionActive = sessionStorage.getItem('justino_session_active');
        const savedUser = localStorage.getItem('justino_user');

        if (isSessionActive && savedUser) {
          const parsedUser = JSON.parse(savedUser);
          setUser(parsedUser);
          setView('dashboard');
        }

        const isAdminActive = sessionStorage.getItem('justino_admin_active');
        if (isAdminActive) {
            setView('admin-dashboard');
        }
    }
  }, []);

  const handleConnectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setIsKeyConnected(true);
    }
  };

  useEffect(() => {
    if (user && view === 'dashboard') {
        localStorage.setItem('justino_user', JSON.stringify(user));

        const fetchCloudData = async () => {
            if (!supabase || !user.id) {
                loadLocalData();
                return;
            }

            try {
                const { data: msgs, error: msgError } = await supabase
                    .from('messages')
                    .select('*')
                    .eq('case_id', user.id)
                    .order('timestamp', { ascending: true });

                if (msgs && !msgError) {
                    const formattedMessages: Message[] = msgs.map(m => ({
                        id: m.id,
                        text: m.text,
                        sender: m.sender,
                        timestamp: new Date(m.timestamp),
                        attachment: m.attachment || undefined
                    }));
                    setMessages(prev => formattedMessages.length > 0 ? formattedMessages : prev);
                }

                const { data: files, error: fileError } = await supabase
                    .from('documents')
                    .select('*')
                    .eq('case_id', user.id)
                    .order('created_at', { ascending: false });

                if (files && !fileError) {
                    const formattedFiles: VaultFile[] = files.map(f => ({
                        id: f.id,
                        name: f.name,
                        type: f.type,
                        content: f.content,
                        origin: f.origin as 'generated' | 'uploaded',
                        date: f.created_at
                    }));
                    setVaultFiles(formattedFiles);
                }
            } catch (e) {
                console.error("Sync Error", e);
                loadLocalData();
            }
        };

        fetchCloudData();
    }
  }, [user, view]);

  const loadLocalData = () => {
    const savedMessages = localStorage.getItem('justino_messages');
    if (savedMessages) {
      setMessages(JSON.parse(savedMessages).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })));
    }
    const savedFiles = localStorage.getItem('justino_vault');
    if (savedFiles) {
      setVaultFiles(JSON.parse(savedFiles));
    }
  };

  const handleStart = () => {
    setView('onboarding');
    setOnboardingStep(1);
  };

  const handleLoginClick = () => {
    setShowLoginModal(true);
  };

  const cancelLogin = () => {
    setShowLoginModal(false);
  };

  const handleLoginSuccess = (loggedInUser: User) => {
    sessionStorage.setItem('justino_session_active', 'true');
    setUser(loggedInUser);
    setShowLoginModal(false);
    setView('dashboard');
  };

  const completeOnboarding = async (newUser: User) => {
    sessionStorage.setItem('justino_session_active', 'true');
    setUser(newUser);
    setView('dashboard');
  };

  const handleLogout = () => {
    sessionStorage.removeItem('justino_session_active');
    setUser(null);
    setMessages([]);
    setVaultFiles([]);
    setView('landing');
  };

  const handleAdminLogout = () => {
    sessionStorage.removeItem('justino_admin_active');
    setView('landing');
  };

  const handleNewMessage = async (msg: Message) => {
    setMessages(prev => [...prev, msg]);
    if (supabase && user?.id) {
        try {
            await supabase.from('messages').insert([{
                id: msg.id,
                case_id: user.id,
                text: msg.text,
                sender: msg.sender,
                timestamp: msg.timestamp.toISOString(),
                attachment: msg.attachment ? msg.attachment : null
            }]);
        } catch (e) {}
    }
    localStorage.setItem('justino_messages', JSON.stringify([...messages, msg]));
  };

  const handleAddFile = async (name: string, type: string, content: string, origin: 'generated' | 'uploaded' = 'generated') => {
    const newFile: VaultFile = {
      id: Date.now().toString(),
      name,
      type,
      date: new Date().toISOString(),
      content,
      origin
    };
    setVaultFiles(prev => [newFile, ...prev]);
    if (supabase && user?.id) {
        try {
            await supabase.from('documents').insert([{
                id: newFile.id,
                case_id: user.id,
                name,
                type,
                content,
                origin,
                created_at: newFile.date
            }]);
        } catch (e) {}
    }
    localStorage.setItem('justino_vault', JSON.stringify([newFile, ...vaultFiles]));
  };

  const hasExistingSession = !!localStorage.getItem('justino_user');

  return (
    <>
      {(!isKeyConnected) && (
        <div className="fixed top-0 left-0 right-0 z-[100] bg-amber-500 text-white p-3 text-center text-xs font-bold uppercase tracking-widest flex items-center justify-center gap-4">
          <span>Justino necesita vincular tu API Key para activarse</span>
          <button onClick={handleConnectKey} className="bg-white text-amber-600 px-4 py-1.5 rounded-full hover:bg-slate-100 transition-colors">
            Activar Ahora
          </button>
        </div>
      )}

      {(view === 'landing' || view === 'onboarding') && (
        <LandingPage 
            onStart={handleStart} 
            onLogin={handleLoginClick}
            onAdminAccess={() => setView('admin-login')} 
            hasExistingSession={hasExistingSession} 
        />
      )}

      {showLoginModal && (
        <LoginModal onSuccess={handleLoginSuccess} onClose={cancelLogin} />
      )}

      {view === 'onboarding' && (
        <OnboardingModal 
          onComplete={completeOnboarding} 
          onClose={() => setView('landing')} 
          initialStep={onboardingStep}
        />
      )}

      {view === 'dashboard' && user && (
        <Dashboard 
          user={user} 
          messages={messages} 
          vaultFiles={vaultFiles}
          onNewMessage={handleNewMessage}
          onAddFile={handleAddFile}
          onLogout={handleLogout}
        />
      )}

      {view === 'admin-login' && (
          <AdminLogin 
            onSuccess={() => {
              sessionStorage.setItem('justino_admin_active', 'true');
              setView('admin-dashboard');
            }} 
            onClose={() => setView('landing')} 
          />
      )}

      {view === 'admin-dashboard' && (
          <AdminDashboard onLogout={handleAdminLogout} />
      )}
    </>
  );
}

export default App;

