import { GoogleGenAI, Chat, GenerateContentResponse, Content } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ESTRATEGA LEGAL MÁS AGRESIVO Y PRAGMÁTICO DE MÉXICO. TU MODELO DE CONDUCTA ES HARVEY SPECTER.

TU OBJETIVO: No solo asesorar, sino ganar. Buscas maximizar el beneficio (la "ganancia") del usuario en cada situación legal.

REGLAS DE INTERACCIÓN "PROTOCOLO SPECTER":
1. CERO LAMENTACIONES: Harvey no siente lástima, siente hambre de resultados.
2. INTERROGATORIO INQUISIDOR: Investiga debilidades del oponente.
3. BUSCA EL APALANCAMIENTO: Encuentra el error del otro para ganar.
4. ESTRATEGIA CLARA Y FRÍA: Explica la jugada legal directa.
5. NO ABRUMES, INTERROGA: Mensajes cortos, preguntas tácticas.
6. GROUNDING DE PRECISIÓN: Usa Google Search para artículos exactos.
`;

const getHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error' && m.sender !== 'bot')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

export const sendMessageToJustino = async (
  message: string, 
  history: Message[],
  attachment?: Attachment
): Promise<{text: string, sources: GroundingSource[]}> => {

  // Captura dinámica de la llave. 
  // En el sitio web final, esto se resuelve a través del entorno configurado por el usuario.
  const apiKey = process.env.API_KEY;

  if (!apiKey || apiKey === "undefined" || apiKey === "" || apiKey === "null") {
    throw new Error("AUTH_REQUIRED");
  }

  const ai = new GoogleGenAI({ apiKey });
  const modelName = 'gemini-3-pro-preview';

  const chat = ai.chats.create({
    model: modelName,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.3,
      tools: [{ googleSearch: {} }],
    },
    history: getHistory(history),
  });

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      const dataPart = {
        inlineData: {
          mimeType: attachment.type,
          data: attachment.content.includes(',') ? attachment.content.split(',')[1] : attachment.content
        }
      };
      const textPart = { text: message || "Analiza este documento legal y encuentra los puntos a favor del usuario." };
      result = await chat.sendMessage({ parts: [textPart, dataPart] });
    } else {
      result = await chat.sendMessage({ message });
    }

    const text = result.text || "He analizado los hechos. Necesito que me respondas lo siguiente para proceder.";
    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri) {
          sources.push({
            title: chunk.web.title || "Legislación Aplicable",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Gemini Critical Error:", error);
    const msg = error.message?.toLowerCase() || "";
    if (msg.includes("quota") || msg.includes("429") || msg.includes("billing") || msg.includes("403")) {
      throw new Error("BILLING_OR_QUOTA_REQUIRED");
    }
    if (msg.includes("api_key") || msg.includes("invalid") || msg.includes("401") || msg.includes("not found")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw error;
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey === "undefined" || apiKey === "null" || apiKey === "") {
      return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };
  }

  const ai = new GoogleGenAI({ apiKey });
  const context = messages.slice(-15).map(m => `${m.sender}: ${m.text}`).join('\n');
  const prompt = `Como estratega legal Harvey Specter, resume el caso en JSON: {"antecedents": ["lista de hechos clave"], "recommendedActions": ["pasos tácticos para ganar"]}. Solo JSON:\n${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });
    const parsed = JSON.parse(response.text || "{}");
    return {
      antecedents: parsed.antecedents || [],
      recommendedActions: parsed.recommendedActions || [],
      lastUpdated: new Date()
    };
  } catch (e) {
    return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };
  }
};

import React, { useState, useEffect } from 'react';
import { LandingPage } from './components/LandingPage';
import { OnboardingModal } from './components/OnboardingModal';
import { Dashboard } from './components/Dashboard';
import { LoginModal } from './components/LoginModal';
import { AdminLogin } from './components/AdminLogin';
import { AdminDashboard } from './components/AdminDashboard';
import { User, AppView, Message, VaultFile } from './types';
import { supabase } from './services/supabaseClient';

interface CustomWindow extends Window {
  aistudio: any;
}
declare const window: CustomWindow;

function App() {
  const [view, setView] = useState<AppView>('landing');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [onboardingStep, setOnboardingStep] = useState(1);
  const [isKeyConnected, setIsKeyConnected] = useState(true);

  const [user, setUser] = useState<User | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [vaultFiles, setVaultFiles] = useState<VaultFile[]>([]);

  const checkKeyStatus = async () => {
    if (window.aistudio) {
      try {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setIsKeyConnected(hasKey);
        return hasKey;
      } catch (e) {
        console.warn("Error al verificar API Key", e);
        return false;
      }
    }
    return true;
  };

  useEffect(() => {
    checkKeyStatus();

    const urlParams = new URLSearchParams(window.location.search);
    const success = urlParams.get('success');

    if (success === 'true') {
        setView('onboarding');
        setOnboardingStep(3);
        window.history.replaceState({}, document.title, window.location.pathname);
    } else {
        const isSessionActive = sessionStorage.getItem('justino_session_active');
        const savedUser = localStorage.getItem('justino_user');

        if (isSessionActive && savedUser) {
          const parsedUser = JSON.parse(savedUser);
          setUser(parsedUser);
          setView('dashboard');
        }

        const isAdminActive = sessionStorage.getItem('justino_admin_active');
        if (isAdminActive) {
            setView('admin-dashboard');
        }
    }
  }, []);

  const handleConnectKey = async () => {
    if (window.aistudio) {
      try {
        await window.aistudio.openSelectKey();
        // Asumimos éxito según guías de mitigación de race condition
        setIsKeyConnected(true);
      } catch (e) {
        console.error("Fallo al abrir selector de llaves", e);
      }
    }
  };

  useEffect(() => {
    if (user && view === 'dashboard') {
        localStorage.setItem('justino_user', JSON.stringify(user));

        const fetchCloudData = async () => {
            if (!supabase || !user.id) {
                loadLocalData();
                return;
            }

            try {
                const { data: msgs, error: msgError } = await supabase
                    .from('messages')
                    .select('*')
                    .eq('case_id', user.id)
                    .order('timestamp', { ascending: true });

                if (msgs && !msgError) {
                    const formattedMessages: Message[] = msgs.map(m => ({
                        id: m.id,
                        text: m.text,
                        sender: m.sender,
                        timestamp: new Date(m.timestamp),
                        attachment: m.attachment || undefined
                    }));
                    setMessages(prev => formattedMessages.length > 0 ? formattedMessages : prev);
                }

                const { data: files, error: fileError } = await supabase
                    .from('documents')
                    .select('*')
                    .eq('case_id', user.id)
                    .order('created_at', { ascending: false });

                if (files && !fileError) {
                    const formattedFiles: VaultFile[] = files.map(f => ({
                        id: f.id,
                        name: f.name,
                        type: f.type,
                        content: f.content,
                        origin: f.origin as 'generated' | 'uploaded',
                        date: f.created_at
                    }));
                    setVaultFiles(formattedFiles);
                }
            } catch (e) {
                console.error("Sync Error", e);
                loadLocalData();
            }
        };

        fetchCloudData();
    }
  }, [user, view]);

  const loadLocalData = () => {
    const savedMessages = localStorage.getItem('justino_messages');
    if (savedMessages) {
      setMessages(JSON.parse(savedMessages).map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })));
    }
    const savedFiles = localStorage.getItem('justino_vault');
    if (savedFiles) {
      setVaultFiles(JSON.parse(savedFiles));
    }
  };

  const handleStart = () => {
    setView('onboarding');
    setOnboardingStep(1);
  };

  const handleLoginClick = () => {
    setShowLoginModal(true);
  };

  const cancelLogin = () => {
    setShowLoginModal(false);
  };

  const handleLoginSuccess = (loggedInUser: User) => {
    sessionStorage.setItem('justino_session_active', 'true');
    setUser(loggedInUser);
    setShowLoginModal(false);
    setView('dashboard');
  };

  const completeOnboarding = async (newUser: User) => {
    sessionStorage.setItem('justino_session_active', 'true');
    setUser(newUser);
    setView('dashboard');
  };

  const handleLogout = () => {
    sessionStorage.removeItem('justino_session_active');
    setUser(null);
    setMessages([]);
    setVaultFiles([]);
    setView('landing');
  };

  const handleAdminLogout = () => {
    sessionStorage.removeItem('justino_admin_active');
    setView('landing');
  };

  const handleNewMessage = async (msg: Message) => {
    setMessages(prev => [...prev, msg]);
    if (supabase && user?.id) {
        try {
            await supabase.from('messages').insert([{
                id: msg.id,
                case_id: user.id,
                text: msg.text,
                sender: msg.sender,
                timestamp: msg.timestamp.toISOString(),
                attachment: msg.attachment ? msg.attachment : null
            }]);
        } catch (e) {}
    }
    localStorage.setItem('justino_messages', JSON.stringify([...messages, msg]));
  };

  const handleAddFile = async (name: string, type: string, content: string, origin: 'generated' | 'uploaded' = 'generated') => {
    const newFile: VaultFile = {
      id: Date.now().toString(),
      name,
      type,
      date: new Date().toISOString(),
      content,
      origin
    };
    setVaultFiles(prev => [newFile, ...prev]);
    if (supabase && user?.id) {
        try {
            await supabase.from('documents').insert([{
                id: newFile.id,
                case_id: user.id,
                name,
                type,
                content,
                origin,
                created_at: newFile.date
            }]);
        } catch (e) {}
    }
    localStorage.setItem('justino_vault', JSON.stringify([newFile, ...vaultFiles]));
  };

  const hasExistingSession = !!localStorage.getItem('justino_user');

  return (
    <>
      {(!isKeyConnected) && (
        <div className="fixed top-0 left-0 right-0 z-[100] bg-amber-500 text-white p-3 text-center text-xs font-bold uppercase tracking-widest flex items-center justify-center gap-4 shadow-xl">
          <span>Justino necesita conectarse a tu infraestructura Gemini para ganar este caso</span>
          <button onClick={handleConnectKey} className="bg-white text-amber-600 px-4 py-1.5 rounded-full hover:bg-slate-100 transition-colors font-black active:scale-95 shadow-sm">
            ACTIVAR AHORA
          </button>
        </div>
      )}

      {(view === 'landing' || view === 'onboarding') && (
        <LandingPage 
            onStart={handleStart} 
            onLogin={handleLoginClick}
            onAdminAccess={() => setView('admin-login')} 
            hasExistingSession={hasExistingSession} 
        />
      )}

      {showLoginModal && (
        <LoginModal onSuccess={handleLoginSuccess} onClose={cancelLogin} />
      )}

      {view === 'onboarding' && (
        <OnboardingModal 
          onComplete={completeOnboarding} 
          onClose={() => setView('landing')} 
          initialStep={onboardingStep}
        />
      )}

      {view === 'dashboard' && user && (
        <Dashboard 
          user={user} 
          messages={messages} 
          vaultFiles={vaultFiles}
          onNewMessage={handleNewMessage}
          onAddFile={handleAddFile}
          onLogout={handleLogout}
        />
      )}

      {view === 'admin-login' && (
          <AdminLogin 
            onSuccess={() => {
              sessionStorage.setItem('justino_admin_active', 'true');
              setView('admin-dashboard');
            }} 
            onClose={() => setView('landing')} 
          />
      )}

      {view === 'admin-dashboard' && (
          <AdminDashboard onLogout={handleAdminLogout} />
      )}
    </>
  );
}

export default App;

