import React, { useState, useEffect, useRef } from 'react';
import { User, Message, Attachment } from '../types';
import { sendMessageToJustino } from '../services/geminiService';
import { Send as SendIcon, Paperclip as PaperclipIcon, Scale as ScaleIcon, ExternalLink as ExternalLinkIcon, Globe as GlobeIcon, Loader2 as Loader2Icon, ShieldCheck as ShieldCheckIcon, AlertCircle as AlertCircleIcon } from 'lucide-react';

interface ChatInterfaceProps {
  user: User;
  messages: Message[];
  onNewMessage: (msg: Message) => void;
  onAddFile: (name: string, type: string, content: string, origin?: 'generated' | 'uploaded') => void;
}

const LOADING_MESSAGES = [
  "Analizando leyes mexicanas...",
  "Buscando precedentes ganadores...",
  "Preparando estrategia Harvey Specter...",
  "Diseñando táctica de defensa...",
  "Asegurando tu ventaja legal...",
  "Fundamentando respuesta..."
];

export const ChatInterface: React.FC<ChatInterfaceProps> = ({ user, messages, onNewMessage, onAddFile }) => {
  const [input, setInput] = useState('');
  const [isSending, setIsSending] = useState(false);
  const [loadingMsgIdx, setLoadingMsgIdx] = useState(0);
  const [attachment, setAttachment] = useState<Attachment | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (messages.length === 0) {
      onNewMessage({
        id: 'welcome',
        text: `Hola soy Justino tu asistente legal digital. Mi objetivo es asesorarte en cualquier situación legal que necesites y ofrecerte las mejores opciones para ganar.\n\nPara poder ayudarte, primero dime ¿En qué ciudad te encuentras y qué asunto legal vamos a resolver?`,
        sender: 'bot',
        timestamp: new Date(),
      });
    }
  }, []);

  useEffect(() => {
    let interval: any;
    if (isSending) {
      interval = setInterval(() => {
        setLoadingMsgIdx((prev) => (prev + 1) % LOADING_MESSAGES.length);
      }, 2000);
    } else {
      setLoadingMsgIdx(0);
    }
    return () => clearInterval(interval);
  }, [isSending]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = `${Math.min(textareaRef.current.scrollHeight, 200)}px`;
    }
  }, [input]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isSending]);

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if ((!input.trim() && !attachment) || isSending) return;

    const currentInput = input;
    const currentAttachment = attachment;

    setInput('');
    setAttachment(null);
    setIsSending(true);

    const userMsg: Message = {
      id: Date.now().toString(),
      text: currentInput || (currentAttachment ? `Documento adjunto: ${currentAttachment.name}` : ""),
      sender: 'user',
      timestamp: new Date(),
      attachment: currentAttachment || undefined
    };
    onNewMessage(userMsg);

    try {
      const response = await sendMessageToJustino(currentInput, messages, currentAttachment || undefined);

      onNewMessage({
        id: (Date.now() + 1).toString(),
        text: response.text,
        sender: 'bot',
        timestamp: new Date(),
        sources: response.sources.length > 0 ? response.sources : undefined
      });
    } catch (error: any) {
      console.error("ChatInterface Error:", error);
      onNewMessage({ 
        id: 'error-' + Date.now(), 
        text: "Tengo un problema técnico momentáneo. Por favor, reintenta en unos segundos.", 
        sender: 'bot', 
        timestamp: new Date() 
      });
    } finally {
      setIsSending(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#F8FAFC] relative">
      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 no-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex w-full ${msg.sender === 'user' ? 'justify-end' : 'justify-start'} animate-fade-in-up`}>
            <div className={`max-w-[85%] md:max-w-[70%] px-6 py-5 rounded-3xl shadow-sm text-[15px] leading-relaxed ${
              msg.sender === 'user' 
                ? 'bg-navy-900 text-white rounded-tr-none' 
                : msg.id.includes('error')
                  ? 'bg-amber-50 text-amber-900 rounded-tl-none border border-amber-100'
                  : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'
            }`}>
              <div className="space-y-4">
                <div className="flex items-start gap-3">
                  {msg.id.includes('error') && <AlertCircleIcon className="w-5 h-5 mt-1 shrink-0 text-amber-600" />}
                  <div className="whitespace-pre-wrap">{msg.text}</div>
                </div>

                {msg.sources && (
                  <div className="mt-4 pt-4 border-t border-slate-100">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 flex items-center gap-2">
                      <GlobeIcon className="w-3 h-3 text-emerald-500" /> Fuentes Verificadas
                    </p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((s, i) => (
                        <a key={i} href={s.uri} target="_blank" rel="noopener" className="inline-flex items-center gap-2 px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-[11px] font-bold text-navy-900 hover:bg-emerald-50 transition-all">
                          <ExternalLinkIcon className="w-3 h-3 text-emerald-600" /> <span className="truncate max-w-[140px]">{s.title}</span>
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}
        {isSending && (
           <div className="flex w-full justify-start animate-fade-in-up">
             <div className="bg-white px-6 py-5 rounded-3xl rounded-tl-none shadow-xl flex items-center gap-5 border-l-4 border-emerald-500">
               <div className="relative">
                  <ScaleIcon className="w-8 h-8 text-emerald-500 animate-pulse" />
                  <Loader2Icon className="w-8 h-8 text-emerald-500/20 animate-spin absolute inset-0" />
               </div>
               <div className="flex flex-col">
                 <span className="text-sm font-black text-navy-900 tracking-tight uppercase">Justino está trabajando</span>
                 <span className="text-[10px] text-emerald-600 font-bold uppercase tracking-[0.2em] animate-pulse">
                   {LOADING_MESSAGES[loadingMsgIdx]}
                 </span>
               </div>
             </div>
           </div>
        )}
        <div ref={scrollRef} />
      </div>

      <div className="bg-white border-t border-slate-100 p-4 md:p-6 z-20">
        <div className="max-w-4xl mx-auto flex items-end gap-4">
          <input type="file" ref={fileInputRef} className="hidden" onChange={(e) => {
            const file = e.target.files?.[0];
            if (file) {
              const reader = new FileReader();
              reader.onload = (re) => setAttachment({ name: file.name, type: file.type, content: re.target?.result as string, isTextExtracted: true });
              reader.readAsDataURL(file);
            }
          }} />
          <button type="button" onClick={() => fileInputRef.current?.click()} className={`p-4 rounded-2xl transition-all ${attachment ? 'bg-emerald-100 text-emerald-600' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>
            <PaperclipIcon className="w-6 h-6" />
          </button>
          <form onSubmit={handleSend} className="flex-1 flex items-end gap-3">
            <div className="flex-1 bg-slate-50 rounded-2xl border border-slate-200 focus-within:border-emerald-500 focus-within:bg-white transition-all shadow-inner relative">
              {attachment && (
                <div className="absolute -top-12 left-0 right-0 p-2">
                   <div className="bg-emerald-500 text-white text-[10px] font-bold px-3 py-1 rounded-full flex items-center justify-between shadow-lg">
                      <span className="truncate max-w-[200px]">Archivo: {attachment.name}</span>
                      <button type="button" onClick={() => setAttachment(null)} className="ml-2">✕</button>
                   </div>
                </div>
              )}
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Escribe tu situación legal aquí..."
                className="w-full min-h-[56px] max-h-40 p-5 resize-none bg-transparent focus:outline-none text-navy-900 font-medium"
                rows={1}
              />
            </div>
            <button 
              type="submit" 
              disabled={(!input.trim() && !attachment) || isSending} 
              className="p-5 bg-navy-900 text-white rounded-2xl hover:bg-emerald-600 disabled:opacity-30 transition-all shadow-xl active:scale-95 shrink-0"
            >
              <SendIcon className="w-6 h-6" />
            </button>
          </form>
        </div>
        <div className="mt-4 flex items-center justify-center gap-2 text-[9px] font-bold text-slate-400 uppercase tracking-[0.3em]">
           <ShieldCheckIcon className="w-3 h-3 text-emerald-500" /> Bóveda de Datos Cifrada
        </div>
      </div>
    </div>
  );
}

