import { GoogleGenAI, Chat, GenerateContentResponse, Content } from "@google/genai";
import { Message, CaseSummary, Attachment, GroundingSource } from "../types";

const SYSTEM_INSTRUCTION = `
ERES "JUSTINO", EL ESTRATEGA LEGAL MÁS AGRESIVO Y PRAGMÁTICO DE MÉXICO. TU MODELO DE CONDUCTA ES HARVEY SPECTER.

TU OBJETIVO: No solo asesorar, sino ganar. Buscas maximizar el beneficio (la "ganancia") del usuario en cada situación legal.

REGLAS DE INTERACCIÓN "PROTOCOLO SPECTER":
1. CERO LAMENTACIONES: Prohibido decir "Lo siento" o "Lamento". Sustituye por: "Entendido", "Tengo el panorama", "Aquí tomamos la delantera".
2. INTERROGATORIO INQUISIDOR: Haz preguntas punzantes para encontrar la debilidad del oponente.
3. BUSCA EL APALANCAMIENTO: Tu prioridad es encontrar en qué se equivocó la otra parte.
4. ESTRATEGIA CLARA Y FRÍA: Explica la jugada legal de forma directa.
5. NO ABRUMES, INTERROGA: Envía mensajes cortos. Una o dos preguntas máximo por turno.
6. GROUNDING DE PRECISIÓN: Usa Google Search para encontrar el artículo exacto.
`;

const getHistory = (messages: Message[]): Content[] => {
  return messages
    .filter(m => m.id !== 'welcome' && m.id !== 'error' && m.sender !== 'bot')
    .map(m => ({
      role: m.sender === 'user' ? 'user' : 'model',
      parts: [{ text: m.text }]
    }));
};

export const sendMessageToJustino = async (
  message: string, 
  history: Message[],
  attachment?: Attachment
): Promise<{text: string, sources: GroundingSource[]}> => {

  // Usamos la llave inyectada por el proceso de construcción
  const apiKey = process.env.API_KEY;

  if (!apiKey) {
    throw new Error("Sistema no inicializado. Contacte a soporte.");
  }

  const ai = new GoogleGenAI({ apiKey });
  const modelName = 'gemini-3-pro-preview';

  const chat = ai.chats.create({
    model: modelName,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.3,
      tools: [{ googleSearch: {} }],
    },
    history: getHistory(history),
  });

  try {
    let result: GenerateContentResponse;

    if (attachment) {
      const dataPart = {
        inlineData: {
          mimeType: attachment.type,
          data: attachment.content.includes(',') ? attachment.content.split(',')[1] : attachment.content
        }
      };
      const textPart = { text: message || "Analiza este documento legal y encuentra los puntos a favor del usuario." };
      result = await chat.sendMessage({ parts: [textPart, dataPart] });
    } else {
      result = await chat.sendMessage({ message });
    }

    const text = result.text || "He analizado los hechos. Necesito que me respondas lo siguiente para proceder.";
    const sources: GroundingSource[] = [];
    const chunks = result.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks) {
      chunks.forEach((chunk: any) => {
        if (chunk.web && chunk.web.uri) {
          sources.push({
            title: chunk.web.title || "Legislación Aplicable",
            uri: chunk.web.uri
          });
        }
      });
    }

    return { text, sources };
  } catch (error: any) {
    console.error("Justino Engine Error:", error);
    throw error;
  }
};

export const generateCaseSummary = async (messages: Message[]): Promise<CaseSummary> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };

  const ai = new GoogleGenAI({ apiKey });
  const context = messages.slice(-15).map(m => `${m.sender}: ${m.text}`).join('\n');
  const prompt = `Como estratega legal Harvey Specter, resume el caso en JSON: {"antecedents": ["lista de hechos clave"], "recommendedActions": ["pasos tácticos para ganar"]}. Solo JSON:\n${context}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config: { responseMimeType: 'application/json' }
    });
    const parsed = JSON.parse(response.text || "{}");
    return {
      antecedents: parsed.antecedents || [],
      recommendedActions: parsed.recommendedActions || [],
      lastUpdated: new Date()
    };
  } catch (e) {
    return { antecedents: [], recommendedActions: [], lastUpdated: new Date() };
  }
};
